let S, pts;

function setup() {
  createCanvas(windowWidth, windowHeight);
	background("rgb(2, 2, 8)");
	describe("rotating and pulsating 2D-Dodecicosacron with varying colors");
	frameRate(60);
	colorMode(HSB,1)

  noFill();
	stroke("silver");
  strokeWeight(2);
	S = max(width, height);

	const num = 10;
	const da = TWO_PI / num;
	pts = [];
	for (let a = 0; a < TWO_PI; a+=da) {
		const x = cos(a) * S/2;
		const y = sin(a) * S/2;
		pts.push({x, y, z: (a%TWO_PI)%1});
		// console.log(`${nf(vec.x, 0, 2)}, ${nf(vec.y, 0, 2)}`);
	}

  loop();
}

function draw() {
	background("rgba(2, 2, 8, 0.1)");
	translate(width/2, height/2)
	rotate(frameCount/88)

	/*
	beginShape();
	for (let i = 0; i < pts.length * 3; i+=3) {
		const p = pts[i%pts.length];
		vertex(p.x, p.y)
	}
	endShape(CLOSE);
	*/

	let lIdx = 0;
	for (let i = 3; i < pts.length * 3 + 3; i += 3) {
		var p = pts[lIdx%pts.length];
		const q = pts[i%pts.length];
		// line(p.x, p.y, q.x, q.y)
		const cf = frameCount/123;
		const c1 = color(fract(cf + p.z/4), 0.7, 0.7);
		const c2 = color(fract(cf + q.z/4+0.8), 0.7, 0.7);
		const f = fract(0.7 + sin(frameCount/44) * 0.2);
		clrLine(p.x * f, p.y * f, q.x * f, q.y * f, c1, c2)
		lIdx = i;
		if (true || ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) strokeWeight(6), stroke("white"), point(q.x * f, q.y * f), strokeWeight(2);
	}

	// // noLoop() removed for animation
}

function noisom(v1, v2) {
	if (v1>v2) [v1, v2] = [v2, v1];
	const n = noise(v1, v2, frameCount/123);
	return v1+n*(v2-v1);
}

function clrLine(x1, y1, x2, y2, c1, c2) {
	// const easings = [easeInOutElastic, easeInOutCubic, easeInCubic];
	// const easing = random(easings);
	const dst = dist(x1, y1, x2, y2);
	for (let i = 0; i <= dst; i++) {
		var f = i/dst;
		var x = lerp(x1, x2, f);
		var y = lerp(y1, y2, f);
		const c = lerpColor(c1, c2, f); // easing(f);
		stroke(c);
		point(x, y);
	}
}

function __mouseClicked() {
  if (mouseButton === LEFT) setup();
}
